using System.Text.Json;using SyWater.Places.Application.Places;using SyWater.Places.Application.Ports.In;using SyWater.Places.Application.Ports.Out;using SyWater.Places.Domain.Places;namespace SyWater.Places.Application.UseCases;public sealed class DeletePlaceUseCase(    IPlaceRepository places,    IDeviceLinkChecker devices,    TimeProvider clock) : IDeletePlaceUseCase{    public async Task ExecuteAsync(Guid ownerId, Guid placeId, CancellationToken ct)    {        var place = await places.GetActiveAsync(placeId, ownerId, ct)                    ?? throw new PlaceNotFoundException(placeId);        if (await devices.HasActiveDeviceAsync(place.Id, ct))            throw new PlaceHasActiveDeviceException(place.Id);        var now = clock.GetUtcNow().UtcDateTime;        var wasDefault = place.IsDefault;        place.Delete(now);        Place? newDefault = null;        if (wasDefault)        {            var remaining = await places.ListActiveAsync(ownerId, ct);            newDefault = remaining                .Where(p => p.Id != place.Id)                .OrderBy(p => p.CreatedAt)                .FirstOrDefault();            newDefault?.MarkAsDefault(now);        }        var activity = new PlaceActivity(            place.Id, ownerId, PlaceActivity.PlaceDeleted,            JsonSerializer.Serialize(new { name = place.Name, wasDefault, newDefaultPlaceId = newDefault?.Id }),            now);        if (!await places.DeleteAsync(place, newDefault, activity, ct))            throw new PlaceNotFoundException(placeId); // two deletes at the same time: the second one loses    }}